) AS (
  VALUES 
    (378::BIGINT, 'Buen profesor, los exámenes no son fáciles pero tampoco difíciles (dos problemas por examen) están al nivel de los ejemplos que da en la clase que son como 2 lo mucho 3 jaja pero por lo general bastante bien. Y lo de humillar a la gente lo veo mas bien de como se expresa que por otra cosa.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Respetado por los estudiantes', 'Clases largas']::TEXT[], '2025-12-04T00:00:00+00:00'::TIMESTAMPTZ, '46f4280a76170ac568c136f76e821a06f3be3f2aaa066803e48ca212dd5ebb08'::TEXT, ARRAY[1257]::BIGINT[]),
    (378::BIGINT, 'Pésimo profesor, humilla a los estudiantes y solo da una clase a la semana.'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-07-22T00:00:00+00:00'::TIMESTAMPTZ, 'e360ceb66b7b13d2415508395a1380bf5013650cea32b9fdbe62822c06ea8c0a'::TEXT, ARRAY[1257]::BIGINT[]),
    (378::BIGINT, 'muy buen profesor me ayudó mucho'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Clases excelentes']::TEXT[], '2025-03-11T00:00:00+00:00'::TIMESTAMPTZ, 'bbfe98c2b7f4c086a86050a2829852d497ef51cb0406fbc993c7d4fdc3b49ab9'::TEXT, ARRAY[1371, 1337]::BIGINT[]),
    (378::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-02-28T00:00:00+00:00'::TIMESTAMPTZ, 'f1855b70a2d72892570615b207411b0a399742afb9d73561b71b011cf9ca4dee'::TEXT, ARRAY[1256]::BIGINT[]),
    (378::BIGINT, 'A veces explica bien, sin embargo tiende a humillar a los estudiantes cuando tienen dudas, ya que no sabe escuchar, tienen que ser muy autodidactas para pasar, ya que solo explica una vez a la semana, manda a leer el libro y luego regaña si uno hace algo que aprendió en el libro,se contradice mucho'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-06-28T00:00:00+00:00'::TIMESTAMPTZ, 'c222ffdae91a614fe890106cc1bac971c8ae6bc3c22a26e7028f483ba31e960f'::TEXT, ARRAY[1257]::BIGINT[]),
    (378::BIGINT, 'Explica medio bien, califica en binario en múltiplos de 10, los exámenes valen poco y califica rudo, se contradice y insulta a sus estudiantes, deja poco material y medio ve los temas por encima, se salta muchos temas ya que los toma como irrelevantes, es un profesor demasiado mediocre'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('50','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Exámenes retadores']::TEXT[], '2024-06-20T00:00:00+00:00'::TIMESTAMPTZ, 'ffbb9cf55880afbc55798dda10461622f95b215d15015f99ba8df380ec3a9def'::TEXT, ARRAY[1257]::BIGINT[]),
    (378::BIGINT, 'Disfruta de la humillación publica del estudiante y no explica nada porque quiere que "aprendamos a hacer las cosas solos". Califica binario, si sabes pasas sino no, pocas evaluaciones pero piénsalo dos veces antes de matricular con él.'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-06-19T00:00:00+00:00'::TIMESTAMPTZ, 'b629d1f0e86386568477af5f1487f118bcf6d61345babb3400d4707fae7bf9d5'::TEXT, ARRAY[1256]::BIGINT[]),
    (378::BIGINT, 'No se los recomiendo para este curso, el profe es algo vago y casi que las propias clases son autodidactas, no explica claramente y no es muy cortes cuando alguien le pregunta algo, las evaluaciones son muy confusas pero sencillas, eso sí casi que no pide evaluaciones durante el semestre.'::TEXT, 8.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clase fácil', 'Asistencia obligatoria']::TEXT[], '2024-06-15T00:00:00+00:00'::TIMESTAMPTZ, 'f8481400c449cc382b8d0576df440f78b8b0a51849f1de32856d87e970690163'::TEXT, ARRAY[1256]::BIGINT[]),
    (378::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Exámenes retadores']::TEXT[], '2024-02-10T00:00:00+00:00'::TIMESTAMPTZ, '5a3b7e38753b7621efdcd5ec895347998c68c656418c8ec9613b5c8c764200d4'::TEXT, ARRAY[1257]::BIGINT[]),
    (378::BIGINT, 'Un chiste de curso. Las clases son puros videos grabados que duran unos 20min cada uno. La evaluacion consistio en quices super faciles y un proyecto que no tiene que ver con la materia del curso, pero diay, es el unico profe que da el curso'::TEXT, 10.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas']::TEXT[], '2023-11-19T00:00:00+00:00'::TIMESTAMPTZ, '371442236212541687b0bf091e6db5c2694a7913dcce1da7518b958d9c553448'::TEXT, ARRAY[1304]::BIGINT[]),
    (378::BIGINT, 'Hay que ser muy autodidacta, pues hace como dos ejemplos y da el tema por visto, se saltó temas porque según él no son importantes, como amplificadores que se utiliza mucho en CA, en los exámenes solamente coloca 2 ejercicios lo que afecta al estudiante por los pocos puntos que vale cada uno'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'd9edd40183b7a0909b2821a6f107831f860af6f2e51a92d6e929c9eea66138b6'::TEXT, ARRAY[1257]::BIGINT[]),
    (378::BIGINT, 'Pésimo "profesor". No se le puede preguntar nada del proyecto porque lo manda a leer el pésimo intento de instrucciones que se hizo. Cuando uno lo llama a revisar mediciones dura horas en bajar 2 pisos para dar un visto bueno. A menos que ud sea mujer no le va a poner atención. Otra joyita electro.'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-23T00:00:00+00:00'::TIMESTAMPTZ, '579f325dac9d742dcbc57bcde7eb3856e5d1fc64d49cc8625bbf75c3ff14deed'::TEXT, ARRAY[1304]::BIGINT[]),
    (378::BIGINT, 'Hace malos chistes, se queja toda la clase que nadie hace preguntas y regaña cuando uno si las hace, también tiene complejo de superioridad y se pasa quejando de sus compañeros. Se desquita con sus estudiantes nunca responde de buena gana, no lo recomiendo como profe para nada.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-16T00:00:00+00:00'::TIMESTAMPTZ, '3fd467e938997719314dd8fdf551f1660fd970b604d11601891c648c8729fcdb'::TEXT, ARRAY[1257]::BIGINT[]),
    (378::BIGINT, 'Se nota frustrado, solitario, parece que no le gusta el trabajo de dar clases, es un poco grosero, responde de mala manera, no se aprende nada, si puede evitarlo mejor, pero si no tiene opción asista y cumpla con los trabajos y pasa fácil. No se confíe si le cae mal, hace lo imposible para dejarla'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura']::TEXT[], '2023-01-28T00:00:00+00:00'::TIMESTAMPTZ, '82b572ff0962c9d8f904faee61d11095bd151daf92a316d681e43df9cc6766d4'::TEXT, ARRAY[1304]::BIGINT[]),
    (378::BIGINT, 'En clases no se aprende mucho, el proyecto no tiene relación directa con la materia del curso, el curso se pasa fácil.'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-29T00:00:00+00:00'::TIMESTAMPTZ, '06e08d6ec4bb750159a157a752d72d13d2e6527cd66abe6e2cee6e2f0ba76b6e'::TEXT, ARRAY[1304]::BIGINT[]),
    (378::BIGINT, 'No se de que trata el curso. Los videos los deje de ver desde semana 2 porque la evaluacion son proyectos que no tenian nada que ver con la materia que se veia. Es un curso bastante facil'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-27T00:00:00+00:00'::TIMESTAMPTZ, '8739706b1001d12cc856cd72a3c046fa2ca4c07d1edf5ea076e10e329d32e1b8'::TEXT, ARRAY[1304]::BIGINT[]),
    (378::BIGINT, 'El profe lo unico que hacia era enviar videos de máximo 30 min todas las clases, los videos no explican mucho , así que lo que se aprende es muy poco. El curso es solo proyecto , el cual no tiene nada que ver con la materia que se ve en los videos. Es un poco arrogante en consulta.'::TEXT, 10.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-22T00:00:00+00:00'::TIMESTAMPTZ, '7418846cef67c9bf4201decbd83b72e45a3701170b1f20e39678a9dda72ab774'::TEXT, ARRAY[1304]::BIGINT[]),
    (378::BIGINT, 'Nunca nos dió una clase entera, simplemente nos mandaba a la página donde había un resumen, y luego al libro todo por nuestra cuenta. Además, cuando uno le pregunta, siempre contesta de la manera más arrogante posible. Trate de evitarlo a toda costa, no matricule ni aunque sea el único profe.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2022-06-12T00:00:00+00:00'::TIMESTAMPTZ, 'c89622a4204e67dfd5a0201929bd067173d8a9e9b515a7ee4fdc51ee7c6e2353'::TEXT, ARRAY[1257]::BIGINT[]),
    (378::BIGINT, 'El profe no le da apoyo a los estudiantes, en virtual, fue el peor profesor que tuve, no da las explicaciones nada bien y casi que es hacer todo el curso uno solo, para peores si uno intenta quejarse o pedir ayuda el mae lo único que hace es hacer la evaluación mucho más díficil sin brindar apoyo'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchos exámenes', 'Exámenes retadores']::TEXT[], '2021-10-19T00:00:00+00:00'::TIMESTAMPTZ, 'a7babd97ece6ce596e2d7bf6d96bc24f364037c8a205bd753571d5e3dcfcb72a'::TEXT, ARRAY[1257]::BIGINT[]),
    (378::BIGINT, 'NO LO HAGAN, ÉL PROFE MÁS MEDIOCRE QUE EXISTE EN EL TEC, VAYA DESPERDICIO DE DINERO'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Muchos exámenes', 'Exámenes retadores']::TEXT[], '2021-10-05T00:00:00+00:00'::TIMESTAMPTZ, '399367d7cddf449408cdeeb740097293cd41708a7e704821c425e1f9a63663b6'::TEXT, ARRAY[1257]::BIGINT[]),
    (378::BIGINT, 'Los exámenes son fáciles y en parejas, y los proyectos son en grupo. EL curso se pasa súper fácil pero se parende poco.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Pocos exámenes', 'Muchos proyectos grupales']::TEXT[], '2021-07-20T00:00:00+00:00'::TIMESTAMPTZ, '5419e8a6e84caf1ec34035b9ceb898d43a5a72a5622f53441c79f2922041aa75'::TEXT, ARRAY[1304]::BIGINT[]),
    (378::BIGINT, 'Llevé el curso en modalidad virtual. Prácticamente no da clases, nos refiere a una pagina donde da un resumen de la materia y a lo mucho un ejemplo, después de eso vaya lea el libro y no espere que haga una clase donde explique. Evítelo si es la primera vez en este curso.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2021-06-11T00:00:00+00:00'::TIMESTAMPTZ, '36b45ac0fdb984fd618983f0325a7aec0da05c244386df565e86ec2e9de43c5d'::TEXT, ARRAY[1257]::BIGINT[]),
    (378::BIGINT, 'El profesor es grosero, arrogante y arbitrario. Sabe muchísimo de electrónica mas no lo sabe transmitir. La modalidad en que lo llevé fue virtual, no explicaba más que uno o dos ejemplos y después nos refería al libro. Si no está llevando el curso por segunda vez, NO matricule con él.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria']::TEXT[], '2021-02-17T00:00:00+00:00'::TIMESTAMPTZ, '1e08a6b426fb7e3f296c5b2518f5fa000232259fdaeb0bcdcdc78521bf58df31'::TEXT, ARRAY[1257]::BIGINT[]),
    (378::BIGINT, 'El curso es liviano, con que entregue los trabajos completos, pasa con buena nota'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchos proyectos grupales']::TEXT[], '2021-02-07T00:00:00+00:00'::TIMESTAMPTZ, '1f11efa4d40b1f49208385716f0f9deccae140a2849d2ae732f2527c65dfa3db'::TEXT, ARRAY[1304]::BIGINT[]),
    (378::BIGINT, 'La clase es asincrónica y corta, los exámenes son sencillos, el proyecto es sencillo también pero tenga un buen grupo porque vale un 70%. Califica muy suave. El problema es que no es muy atento con las clases, pero en si es buen profesor.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Pocos exámenes', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2021-02-03T00:00:00+00:00'::TIMESTAMPTZ, '57a551863557c31927ca709ca8a86c13dd5dce7a027e1e33931cb1e21fbda1fe'::TEXT, ARRAY[1304]::BIGINT[]),
    (378::BIGINT, 'Hizo el curso asincrónico, los exámenes son sencillos, le recomiendo tener un buen grupo de trabajo porque el proyecto vale 70%(esta dividido en etapas). Participen con los foros, y si ocupan más tiempo para entregar algo él comprende.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Muchos proyectos grupales']::TEXT[], '2021-01-27T00:00:00+00:00'::TIMESTAMPTZ, '4b1de6eff9d31bd93b84d1df715a44722cac6ecad02d40be08c9e5bc3b362bea'::TEXT, ARRAY[1304]::BIGINT[]),
    (378::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2020-12-27T00:00:00+00:00'::TIMESTAMPTZ, '2cc087d87ddcc421bfbe8b82f9096b8896c5607a0a7b5bc374918d4fa3cb13cd'::TEXT, ARRAY[1304]::BIGINT[]),
    (378::BIGINT, 'Excelente profesor, enseña para la vida. Ayuda, respeta a los estudiantes, le gusta la disciplina, ordenado, GRAN PERSONA, comprensivo. SÚPER RECOMENDADO. ES EXCELENTE'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Inspirador', 'Da crédito extra']::TEXT[], '2020-11-06T00:00:00+00:00'::TIMESTAMPTZ, '4f1bd8a1e7a0af8f46d2d2c41b5176f524cfaceeefed98b8ec7b346eda8397f0'::TEXT, ARRAY[1257]::BIGINT[]),
    (378::BIGINT, 'Entre atrasarme 15 años de carrera y llevar con él otra vez, prefiero atrasarme los 15 años. Pésimo, arrogante, pretende que vayan a sus clases sabiendo todo, califica binario, no le gusta la retroalimentación. La vez que casi TODO mi grupo perdió un examen, dijo que era culpa nuestra. No lo haga.'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Exámenes retadores']::TEXT[], '2020-09-07T00:00:00+00:00'::TIMESTAMPTZ, '88a6ff1d30f31462c2748ec04d2fb55fa30721d8342f23a8de7ae76cee0008b8'::TEXT, ARRAY[1257]::BIGINT[]),
    (378::BIGINT, 'Es una lástima que un curso que podría ser muy tuanis termine siento tan malo. No sabe nada de potencia y a final de cuentas lo poco que usted aprende (si aprende algo) es de máquinas eléctricas'::TEXT, 10.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-16T00:00:00+00:00'::TIMESTAMPTZ, 'ba08c21fe5d4c0a71829c14212bd1d3f4fa8ff2acb7e0dd58bb5d4468e7721b7'::TEXT, ARRAY[1304]::BIGINT[]),
    (378::BIGINT, 'De lejos el peor profesor con el que he tenido la desdicha de cursar, se jacta de que es super correcto cuando le ayuda más a las mujeres que a los hombres. Si matricula con él prepárese a pasar el semestre a puro tutorial de youtube.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-14T00:00:00+00:00'::TIMESTAMPTZ, '8f49d1d4513721286ebc1b5cdbb3e4a45297cc2324f62a70ca08b6e4873f6389'::TEXT, ARRAY[1257]::BIGINT[]),
    (378::BIGINT, 'Cuando llevé el curso, empezó con los dos primeros exámenes súper bien, hacía varios ejercicios y así. Sin embago, al llegar a los últimos dos, dejó de explicar bien, hacía solo UN ejercicio de cada tema. Además se queja que nadie va a consulta, pero uno va y es súper repugnante.'::TEXT, 8.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-01-29T00:00:00+00:00'::TIMESTAMPTZ, '632e34130a4e3069017a8c24af95ace86bf45db5fa1f878cc0e2707af35f0b06'::TEXT, ARRAY[1257]::BIGINT[]),
    (378::BIGINT, 'El mae es medio raro, solo con algunas personas es buena nota, no se aprende casi nada de Potencia solo convertidores CD-CD y no queda de otra porque es el único que lo da'::TEXT, 10.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-01-18T00:00:00+00:00'::TIMESTAMPTZ, '50a6611815c889827659285f4b2b34f8c220f170fc7b577cb055371c34c565c3'::TEXT, ARRAY[1304]::BIGINT[]),
    (378::BIGINT, 'De los peores profesores del TEC. Pide retroalimentación y niega todo lo que se le dice poniendo excusas. No abarca todos los temas que se tienen que dar, implica que la preparación para el estudiante es mala. Califica binario, o tiene todo bueno, o todo malo.'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clase fácil', 'Asistencia obligatoria']::TEXT[], '2019-12-09T00:00:00+00:00'::TIMESTAMPTZ, '9893c5aeb7d88f974ec610428361197aec600bafd118a75f0cb263f7405d13f8'::TEXT, ARRAY[1257]::BIGINT[]),
    (378::BIGINT, 'Tuve la desgracia que me cambiaran al profe de intro 2 después de haber llevado intro 1 con él. Pésima actitud, no le gusta ayudar en cosas básicas EN UN CURSO DE INTRODUCCIÓN. Solamente le ayudaba a las dos muchachas del grupo el viejo verde.'::TEXT, 10.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases largas']::TEXT[], '2019-11-24T00:00:00+00:00'::TIMESTAMPTZ, '4c5466edb3fcd9e0080f31ae856c421ba2c5a60b3d620022b60d9325106d3c08'::TEXT, ARRAY[1252]::BIGINT[]),
    (378::BIGINT, 'La verdad no sé que pasó este semestre, pero este profesor fue pésimo, nunca acepto la retroalimentación que le dieron los estudiantes poniendo un montón de excusas, se pasó como 4 temas por donde le dio la gana y nada más no los dio, es prepotente, aburrido y hace exámenes de 12 y 16 puntos.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('45','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-11-22T00:00:00+00:00'::TIMESTAMPTZ, '9a3f617cf685333c8ca502b22905dfa154fe19b061f6eac03cecb12b100c0596'::TEXT, ARRAY[1257]::BIGINT[]),
    (378::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil', 'Requiere mucha lectura', 'La participación importa']::TEXT[], '2019-11-20T00:00:00+00:00'::TIMESTAMPTZ, '0d2454e9f835fde86e0952925125015cd81b5a053a370f099fc082f887874a6a'::TEXT, ARRAY[1257]::BIGINT[]),
    (378::BIGINT, 'Mal profe, pero como enseña revisa, fácil, llévelo si está repitiendo o lo van a sonar en CA.'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil', 'Da crédito extra', 'Brinda apoyo']::TEXT[], '2019-06-25T00:00:00+00:00'::TIMESTAMPTZ, '520d81e36d8a01da417e465a2bf1c6a24ffd3a27d9896599a2045d14596c064e'::TEXT, ARRAY[1257]::BIGINT[]),
    (378::BIGINT, 'El curso se debería llamar: Transformadores y Maquinas Eléctricas 2.0, ya que la materia vista en clase no tiene que ver con potencia. Lo único que se ve de potencia es la parte de convertidores CD-CD, el resto es materia reciclada de cursos que ya no están en la malla.'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-19T00:00:00+00:00'::TIMESTAMPTZ, '4781e909b72018bcbd6f4134d604deb6e9e47431cc21ac84645dad192c3e1240'::TEXT, ARRAY[1304]::BIGINT[]),
    (378::BIGINT, 'Excelente profesor, nunca faltara las clases, ni a los centros extras que da.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Deja trabajos largos', 'Clases excelentes']::TEXT[], '2019-06-07T00:00:00+00:00'::TIMESTAMPTZ, '239aa8ba00e8d5c1b91aba161787c9bd6ab32171237887061cbdf4a65890ce61'::TEXT, ARRAY[1257]::BIGINT[]),
    (378::BIGINT, 'El profesor explica bien, pero solo lo necesario para un examen, por lo que no se aprende casi nada de lo que se debería para los siguientes cursos, no distribuye bien las lecciones, si te agarra entre ojos mamaste, cuenta chistes muy malos que hasta te va a dar pena ajena.'::TEXT, 8.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'La participación importa', 'Asistencia obligatoria']::TEXT[], '2019-05-31T00:00:00+00:00'::TIMESTAMPTZ, '1fd8fac07505cb995881246c1e9ff18e5ea2268b86bd8b59b0bbefb1b794030d'::TEXT, ARRAY[1257]::BIGINT[]),
    (378::BIGINT, 'Pésimo profesor.. Alguien que le avise que el curso es potencia, no máquinas, que acepte que ese curso ya no está. Por favor traigan a bigotes de vuelta, él si sabía dar el curso.'::TEXT, 10.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-05-30T00:00:00+00:00'::TIMESTAMPTZ, '8ed9d8d518406a92772977d9aab98f7a1d3a7d9b8c5f7312767198e8c11a8d29'::TEXT, ARRAY[1304]::BIGINT[]),
    (378::BIGINT, 'El profe explica lo necesario para que uno entienda la materia, en consulta saca el rato para explicarle lo que uno necesita, lo enseña a uno a razonar y no aprenderse recetas.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2019-05-30T00:00:00+00:00'::TIMESTAMPTZ, 'b78b6113963927d07c66ccfcd59ea466c0e6df7045ce81de5aac319542c3eb6d'::TEXT, ARRAY[1257]::BIGINT[]),
    (378::BIGINT, 'pros: -si ud va a clases entiende(y el mae lo nota)(manda huevo) -lo pone a razonar(a mi me sirvió) -los exámenes son de un nivel razonable contras: -analogias rarisimas -explica como si se le estuviera cagando -avisa de las tareas de un dia para otro pd: yo no noté una actitud rara con las mujeres'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases largas', 'Clases excelentes']::TEXT[], '2018-11-28T00:00:00+00:00'::TIMESTAMPTZ, 'b4acc7287d8564a4146cba089e4bb709a6c8bfcbf94414dab8d9bb1a67d1708e'::TEXT, ARRAY[1257]::BIGINT[]),
    (378::BIGINT, 'La clase es sumamente mala, no se aprende nada y el profesor se le nota el claro favoritismo para con las mujeres, ya está demasiado viejo para ponerse en eso. Lamentable que existan profesores así'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-10-24T00:00:00+00:00'::TIMESTAMPTZ, '3a5ef407d1e0fb55be0b137c4668214463dd3f3bb25910f7dc88d60e58f00380'::TEXT, ARRAY[1371, 1337]::BIGINT[]),
    (378::BIGINT, 'Simplemente es un profesor que no explica nada. Pasé el curso con buena nota pero es pésimo, además si eres mujer, no lo dudes, va intentar algo contigo.'::TEXT, 10.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases largas', 'Deja trabajos largos']::TEXT[], '2018-09-27T00:00:00+00:00'::TIMESTAMPTZ, 'ef7fb44ea1f5b18892fb5f6af97e4de1f660dae1f9668664c2b45fee38b87f34'::TEXT, ARRAY[1262]::BIGINT[]),
    (378::BIGINT, 'Si usted es MUJER: te va a querer coger!!!! Se va en hablada echándole el cuento a las compas...y ya está bieen roco para esas.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-09-06T00:00:00+00:00'::TIMESTAMPTZ, '69799ed4bcd046aecda7c1703ef9edb7ef58dc83dddc9bcd5488f107e144bf97'::TEXT, ARRAY[1257]::BIGINT[]),
    (378::BIGINT, 'Es un desgraciado que cree que tiene conocimiento absoluto. Es un hipócrita y si no le cae bien ya está predispuesto a una mala nota. Habla de mejorar cursos y es peor que otros que hacen igual o menos.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Deja trabajos largos']::TEXT[], '2018-07-06T00:00:00+00:00'::TIMESTAMPTZ, '3d59452e41aa855a277fe1fed45f94ff29f1875746e7f1e54b6922d8e37b4e7d'::TEXT, ARRAY[1380, 1351]::BIGINT[]),
    (378::BIGINT, 'El profesor hay que ir a buscarlo a la oficina por que se desentiende del curso, a veces es dificil de tratar pero en general el curso es muy fácil entonces terminas pasando.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-30T00:00:00+00:00'::TIMESTAMPTZ, '40d68c5a9d64a14263281deed1a4090e75be05fe690d095d91e645567ff662c7'::TEXT, ARRAY[958, 960]::BIGINT[]),
    (378::BIGINT, 'Pro: se le entiende lo que explica, hace exámenes fáciles y no usa presentaciones. Contras: que habla mucha paja en clase y puede ser bastante aburrido. Pero en general lo recomiendo, hace que RLC sea mas sencillo de ver y entender para los que no han llevado Ecuaciones Diferenciales.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'a2dc1688f1fd0061ba908588a077f4a0d0d9803d1d4fe74a4afb9ffb1361b151'::TEXT, ARRAY[1257]::BIGINT[]),
    (378::BIGINT, 'Si lo que quiere es pasar el curso matricule con él, los ejercicios en clase son super sencillos pero pone al estudiante a resolverlo por su propia cuenta con esto se desperdia demasiado tiempo, el examen es un regalo, si no pasa con él es por vago!!'::TEXT, 10.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-21T00:00:00+00:00'::TIMESTAMPTZ, '9abafa81369bedbe644c2aa8bf2f523171ddb4ca770f98f30ae7e5a17ca50456'::TEXT, ARRAY[1257]::BIGINT[]),
    (378::BIGINT, 'Buen Profe, trata de explicar lo mejor que puede, pero hace un ejercicio y luego deja que los estudiantes traten de resolverlos solos, pero se desperdicia mucho tiempo, hay que practicar bastante por su cuenta'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-18T00:00:00+00:00'::TIMESTAMPTZ, 'a3528f4a83921f2abedbfc75d658efb6ac8beb365dd0dacf43227dacc5039072'::TEXT, ARRAY[1257]::BIGINT[]),
    (378::BIGINT, 'Es el peor profe con el que he llevado clases, quiere ser gracioso para opacar su deficiencia al explicar, no hace mucha práctica y los pocos ejemplos que hace son demasiado básicos, no acepta cuando se equivoca, califica rudísimo y es muy difícil tratar con él. MEJOR NO MATRICULE CON ÉL????'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('45','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria']::TEXT[], '2018-01-31T00:00:00+00:00'::TIMESTAMPTZ, '593a36863cf3475224766e26d7e477721aaae30f889510825f43d3f352994eac'::TEXT, ARRAY[1257]::BIGINT[]),
    (378::BIGINT, 'Explica bien, se preocupa por enseñar conceptos importantes pero a veces se devuelve a cosas muy básicas que hacen aburrida la clase. El profe es un poco raro, a veces llega de buenas o de malas y le molesta mucho que hagan ruido o estén distrayendo a otros en clase.'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-01-28T00:00:00+00:00'::TIMESTAMPTZ, '7b120fd7ccfd3453c825beb9d9d9ac16cceb14fba0eb0218fc5bc73fc4674934'::TEXT, ARRAY[1371]::BIGINT[]),
    (378::BIGINT, 'Naah, peor es nada. Ni muy bueno ni muy malo, simplemente prepárese para estudiar mucho por sí mismo. Es muy difícil tratar con él'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria']::TEXT[], '2017-11-30T00:00:00+00:00'::TIMESTAMPTZ, '59d0b7bc1ffd237ac8464ca47bd3bad806a82822e85909b8bf2d0b9fa74d97c2'::TEXT, ARRAY[1257]::BIGINT[]),
    (378::BIGINT, 'Evaluaciones Faciles, domina la materia, excelente profesor. Un poco arrogante.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-11-16T00:00:00+00:00'::TIMESTAMPTZ, '0ff357c396491070aba08c4bf79039bd83b8f771ea9ad517900da62d20c02938'::TEXT, ARRAY[1371]::BIGINT[]),
    (378::BIGINT, 'Es una persona complicada. En varios casos explica bien, pero gasta mucho tiempo hablando cosas innecesarias (como de lo "buen" profe que es) y es muy arrogante. Tampoco acepta cuando se equivoca. Si a usted solo le interesa que explique relativamente bien, matricule con él.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-09-29T00:00:00+00:00'::TIMESTAMPTZ, 'c9cbc0e67b8d6e73cee60718c45c32401f41802e9f0053091b94a5a621949320'::TEXT, ARRAY[1257]::BIGINT[]),
    (378::BIGINT, 'Excelente profesor, domina super bien la materia, se aprende bastante, es buena gente, los exámenes son muy accesibles, los quices son accesibles. Muy buen profesor!!!!!!!!!!'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'ea7e66411f19aa82f335762841f051126eb1bfba2c9b517b4c358a9695d0f78a'::TEXT, ARRAY[1371]::BIGINT[]),
    (378::BIGINT, 'Excelente profe'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Inspirador']::TEXT[], '2017-01-27T00:00:00+00:00'::TIMESTAMPTZ, 'c437264581e55523e17ca762392f2076f7394918efa13a74535e7dcc5123d03a'::TEXT, ARRAY[1257]::BIGINT[]),
    (378::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Inspirador', 'Brinda apoyo']::TEXT[], '2017-01-18T00:00:00+00:00'::TIMESTAMPTZ, 'ffa2232ba8ea627387e89f8aeea6dbdc43618efc411fd8922f59c766ffa4c694'::TEXT, ARRAY[958, 960]::BIGINT[]),
    (378::BIGINT, 'Una picha de profesor, no sabe una mierda y le cuadra echarle el cuento a las compañeras, el peor del TEC, por algo sólo le dan este curso'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-01-18T00:00:00+00:00'::TIMESTAMPTZ, 'fc21d0608300df42723da957064eab3ee91c60d68f6f10365f99bcc6cbde78f5'::TEXT, ARRAY[959, 962]::BIGINT[]),
    (378::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-06T00:00:00+00:00'::TIMESTAMPTZ, '5dbc89b50fc111232afdbe1896601089c3ba4fd979f4f08a8ff07c4d2ae1057f'::TEXT, ARRAY[959, 962]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
